const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Pittsburgh location
  const pittsburgh = ee.Geometry.Point([-80.0, 40.4]);

  // Function to get mean temperature for a February
  function getFebTemp(year) {
    const startDate = ee.Date.fromYMD(year, 2, 1);
    const endDate = ee.Date.fromYMD(year, 3, 1);

    const col = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
      .filterDate(startDate, endDate)
      .select('temperature_2m')
      .filterBounds(pittsburgh);

    const size = col.size().getInfo();
    if (size === 0) return null;

    const meanImg = col.mean();
    const temp = meanImg.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: pittsburgh,
      scale: 11132,
      maxPixels: 1e9
    }).get('temperature_2m').getInfo();

    return temp;
  }

  // Get temperatures for all years
  const temps = {};
  const years = [2010, 2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018];

  for (let year of years) {
    const temp = getFebTemp(year);
    if (temp === null || temp === undefined) {
      console.log(`No data for Feb ${year}`);
      console.log("<answer>C1</answer>");
      return;
    }
    // Convert Kelvin to Celsius
    temps[year] = temp - 273.15;
    console.log(`Feb ${year}: ${temps[year].toFixed(2)}°C`);
  }

  // Check if 2018 was warmest
  const temp2018 = temps[2018];
  let isWarmest = true;

  for (let year = 2010; year <= 2017; year++) {
    if (temps[year] >= temp2018) {
      isWarmest = false;
      break;
    }
  }

  console.log(`\n2018 warmest: ${isWarmest}`);

  if (isWarmest) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
